#!/bin/sh
# Name: RoyalRoadTools-Cleanup
# One-time cleanup of finished Royal Road Kindle experiments.
# Preserves the pending KPP bundle scan/uploader, KPM updater and KOReader repair.

DOCS="/mnt/us/documents"
DB="/var/local/KPPBrowser.db"
BACKUP_DIR="$DOCS/RoyalRoadTools-backups"
DONE_FILE="$DOCS/RoyalRoadTools-Cleanup.done"
PACKAGE_DIR="/mnt/us/kmc/kpm/packages/royalroad-kindle-tools"
BOOKMARK_HEX=""
CLEANUP_OK=1

say() { printf '%s\n' "$*"; }

say "============================================================"
say "ROYAL ROAD KINDLE TOOLS — CLEANUP OF FINISHED TESTS"
say "Preserving: RR-KPP-Bundle-Scan, RR-Upload-Bundle-Scan, KPM-Update-All and KindleBatchPrepareFix."

# Remove only the precise old bookmark URL, after a database backup.
if [ -f "$DB" ]; then
  if command -v sqlite3 >/dev/null 2>&1; then
    TABLE_COUNT="$(sqlite3 -cmd '.timeout 5000' "$DB" "SELECT COUNT(*) FROM sqlite_master WHERE type='table' AND name='bookmark';" 2>/dev/null)"
    if [ "$TABLE_COUNT" = "1" ]; then
      EXISTING="$(sqlite3 -cmd '.timeout 5000' "$DB" "SELECT COUNT(*) FROM bookmark WHERE url=CAST(X'$BOOKMARK_HEX' AS TEXT);" 2>/dev/null)"
      case "$EXISTING" in
        ''|*[!0-9]*)
          say "WARNING: Could not verify the old bookmark; browser database was not changed."
          CLEANUP_OK=0
          ;;
        0)
          say "The old Royal Road Session Test bookmark is already absent."
          ;;
        *)
          mkdir -p "$BACKUP_DIR"
          BACKUP="$BACKUP_DIR/KPPBrowser-before-RR-cleanup-$(date '+%Y%m%d-%H%M%S').db"
          if sqlite3 -cmd '.timeout 5000' "$DB" ".backup '$BACKUP'" >/dev/null 2>&1; then
            if sqlite3 -cmd '.timeout 5000' "$DB" "DELETE FROM bookmark WHERE url=CAST(X'$BOOKMARK_HEX' AS TEXT);" >/dev/null 2>&1; then
              VERIFY="$(sqlite3 -cmd '.timeout 5000' "$DB" "SELECT COUNT(*) FROM bookmark WHERE url=CAST(X'$BOOKMARK_HEX' AS TEXT);" 2>/dev/null)"
              if [ "$VERIFY" = "0" ]; then
                say "Removed and verified the exact old Royal Road Session Test bookmark."
                rm -f "$BACKUP"
              else
                say "WARNING: Bookmark verification failed; safety backup retained at $BACKUP"
                CLEANUP_OK=0
              fi
            else
              say "WARNING: Bookmark deletion failed; safety backup retained at $BACKUP"
              CLEANUP_OK=0
            fi
          else
            say "WARNING: Could not create a browser database backup; no bookmark was changed."
            CLEANUP_OK=0
          fi
          ;;
      esac
    else
      say "WARNING: Browser bookmark table not found; database was not changed."
      CLEANUP_OK=0
    fi
  else
    say "WARNING: sqlite3 unavailable; bookmark was not changed."
    CLEANUP_OK=0
  fi
else
  say "WARNING: Browser database not found; bookmark removal could not be verified."
  CLEANUP_OK=0
fi

# Delete old backup files created by the retired bookmark test, but only when
# the exact bookmark is confirmed absent.
if [ "$CLEANUP_OK" -eq 1 ] && [ -d "$BACKUP_DIR" ]; then
  for FILE in "$BACKUP_DIR"/KPPBrowser-before-RR-bookmark-*.db "$BACKUP_DIR"/KPPBrowser-before-RR-bookmark-removal-*.db "$BACKUP_DIR"/KPPBrowser-before-RR-cleanup-*.db; do
    [ -f "$FILE" ] && rm -f "$FILE"
  done
  rmdir "$BACKUP_DIR" 2>/dev/null || true
  say "Removed the old RoyalRoadTools browser database backups."
fi

# Obsolete launchers from completed experiments.
for ITEM in RR-JS-Smoke-Test.sh RR-LIPC-Metadata-Check.sh RR-Upload-Diagnostic.sh RoyalRoadTools.sh KindleBatchPrepareDiagnostics.sh; do
  [ -f "$DOCS/$ITEM" ] && rm -f "$DOCS/$ITEM"
done

# Obsolete logs, temporary links, and shell status files.
for ITEM in RR-JS-Smoke-Test.log RR-JS-Smoke-Test-upload-url.txt RR-JS-Smoke-Test-delete-url.txt \
  RR-Upload-Diagnostic.log KindleBatchPrepareDiagnostics.log KindleBatchPrepareFix.log \
  RoyalRoadTools-package.log RoyalRoadTools-install.log RoyalRoadTools-launch.log \
  RoyalRoadTools-bookmark.log RoyalRoadTools.log KPM-Update-All.log \
  RR-KPP-Bundle-Scan-upload-url.txt RR-KPP-Bundle-Scan-delete-url.txt RR-Upload-Bundle-Scan.log; do
  [ -f "$DOCS/$ITEM" ] && rm -f "$DOCS/$ITEM"
done

for FILE in "$DOCS"/RoyalRoadTools-test-*.log "$DOCS"/.RoyalRoadTools-launch-status.* \
  "$DOCS"/.RoyalRoadTools-install-status.* "$DOCS"/.KindleBatchPrepareFix-status.* \
  "$DOCS"/.RR-JS-Smoke-Test-upload-*.txt "$DOCS"/.RR-JS-Smoke-Test-response-*.txt \
  "$DOCS"/.RR-JS-Smoke-Test-headers-*.txt; do
  [ -f "$FILE" ] && rm -f "$FILE"
done

# Remove the old bookmarklet's source/URL from the unpacked user-storage KPM copy, if present.
if [ -d "$PACKAGE_DIR" ]; then
  rm -f "$PACKAGE_DIR/bookmarklets/chapter-session-test.jsurl"
  rm -f "$PACKAGE_DIR/tools/add-browser-bookmark.sh" "$PACKAGE_DIR/tools/remove-browser-bookmark.sh"
  rmdir "$PACKAGE_DIR/bookmarklets" "$PACKAGE_DIR/tools" 2>/dev/null || true
fi

if [ "$CLEANUP_OK" -eq 1 ]; then
  printf 'completed=%s\n' "$(date '+%Y-%m-%d %H:%M:%S')" > "$DONE_FILE"
  chmod 600 "$DONE_FILE" 2>/dev/null || true
  say ""
  say "CLEANUP SUCCESSFUL."
  say "Old bookmark, finished test launchers, old logs, upload URLs and test backups are removed."
  say "The pending KPP bundle scan and uploader were preserved."
  say "Removing this one-time cleanup launcher."
  rm -f "$DOCS/RoyalRoadTools-Cleanup.sh"
  exit 0
fi

say ""
say "CLEANUP PARTIAL: old launchers/logs were cleaned, but bookmark removal could not be verified."
say "The cleanup launcher remains available so this can be retried."
exit 1
